INSERT INTO feature VALUES('binary-naturals','types','Binary natural numbers','nominal-data','implemented','ordinary',NULL,'The prelude declares the naturals in binary: `Nat`, `Zero` or `Positive` over a `Pos`, whose `One`, `Bit0` and `Bit1` put the lowest digit outermost, as Isabelle/HOL''s `num` does. A numeral annotated `(n : Nat)` is the constructor term its binary digits spell, `(5 : Nat)` being `Positive(Bit1(Bit0(One)))`, so an order or a sum over the naturals is decided by conversion and replayed by the kernel, where a native `Integer` stays an opaque constant; the printer spells the term back as its numeral. A name a source writes shadows the prelude''s: its own `Nat` keeps its numerals integers, its own type `One` reads as itself, and a code''s leaf naming `Nat` reads the source''s.','surface-lowering surface-pretty','corpus/ledger/features/binary-naturals.gandr corpus/model/effects/grade-algebra.gandr corpus/model/metaprograms/derive-eq-over-codes.gandr corpus/pathological/identity/univalence.gandr crates/surface-lowering/src/lower/natural/tests.rs::a_numeral_at_nat_is_its_binary_constructor_term_3287 crates/surface-lowering/src/lower/natural/tests.rs::a_numeral_at_a_source_s_own_nat_stays_an_integer_3287 crates/surface-lowering/src/lower/generic/tests.rs::a_leaf_reads_a_source_s_family_before_the_prelude_s_3287 crates/surface-lowering/tests/namespace.rs::a_source_s_type_shadows_the_prelude_s_constructor_3287 crates/surface-pretty/tests/goldens.rs::an_ascribed_binary_natural_spells_as_its_numeral_3287','corpus/ledger/features/binary-naturals.gandr',NULL);
